 "content": "from collections import deque


def transform(grid):
    """Encode the counts of 3- and 2-colored horizontal objects in 2x3 form."""
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {3: 0, 2: 0}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in counts or (r, c) in seen:
                continue
            counts[color] += 1
            seen.add((r, c))
            queue = deque([(r, c)])
            while queue:
                rr, cc = queue.popleft()
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        queue.append((nr, nc))
    tokens = [3] * counts[3] + [2] * counts[2]
    tokens = (tokens + [0] * 6)[:6]
    return [tokens[:3], tokens[3:]]


